<?php
declare(strict_types=1);namespace App\Command;
use App\Imperium\Runtime\Citadel\LegateBoundedCognitionTurnService;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\{InputArgument,InputInterface,InputOption};use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name:'imperium:legate:perform-bounded-cognition-turn',description:'Consume one exact provider activation for one governed Legate cognition turn.')]
final class LegatePerformBoundedCognitionTurnCommand extends Command{public function __construct(private readonly LegateBoundedCognitionTurnService$service){parent::__construct();}protected function configure():void{$this->addArgument('provider-activation-id',InputArgument::REQUIRED)->addOption('json',null,InputOption::VALUE_NONE);}protected function execute(InputInterface$i,OutputInterface$o):int{try{$r=$this->service->perform((string)$i->getArgument('provider-activation-id'),new \DateTimeImmutable());}catch(\Throwable$e){$o->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}$o->writeln($i->getOption('json')?json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR):'<info>'.$r['status'].'</info> '.$r['turn_id']);return self::SUCCESS;}}
